import{_ as e,o as d,c as a,a2 as n}from"./chunks/framework.Cm6XCzck.js";const p=JSON.parse('{"title":"4. 已执行测试基线","description":"","frontmatter":{},"headers":[],"relativePath":"zh/publications/implementation-case-i0.7/part-02.md","filePath":"zh/publications/implementation-case-i0.7/part-02.md","lastUpdated":1786282064000}'),r={name:"zh/publications/implementation-case-i0.7/part-02.md"};function s(o,t,i,l,c,g){return d(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="_4-已执行测试基线" tabindex="-1">4. 已执行测试基线 <a class="header-anchor" href="#_4-已执行测试基线" aria-label="Permalink to &quot;4. 已执行测试基线&quot;">​</a></h1><p>全部主要运行均由作者在锁定源码上执行。跳过项不会被换算为通过项。</p><table tabindex="0"><thead><tr><th>轨道</th><th style="text-align:right;">结果</th><th style="text-align:right;">Exit</th><th>解释</th></tr></thead><tbody><tr><td>外部 S0.5 产品夹具</td><td style="text-align:right;">15/15 断言</td><td style="text-align:right;">0</td><td>C01–C14 强制产品级 Bundle</td></tr><tr><td>CodeFlowMu 内置 TMPA 套件</td><td style="text-align:right;">19/19 测试</td><td style="text-align:right;">0</td><td>产品准则映射回归</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">通过</td><td style="text-align:right;">0</td><td>协议测试，与符合性裁决分开</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,446 passed、0 failed、1 skipped</td><td style="text-align:right;">0</td><td>锁定的完整 Runtime 运行</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">775/775</td><td style="text-align:right;">0</td><td>初始化后的隔离产品实例</td></tr><tr><td>Protocol / Runtime / Shell Typecheck</td><td style="text-align:right;">全部通过</td><td style="text-align:right;">0</td><td>仅静态检查</td></tr><tr><td>FCoP 3.2.4 源码基线</td><td style="text-align:right;">1,210 passed、2 skipped</td><td style="text-align:right;">0</td><td>迁移布局下两个历史样例跳过</td></tr></tbody></table><p>准则聚合结果为 <strong>14 PASS / 0 PARTIAL / 0 NOT RUN / 0 FAIL</strong>。这是固定 I0.7 Bundle 的产品结果，不是从 Reference Reader 继承的结果，也不是覆盖所有部署的普遍定理。</p><h1 id="_5-c01–c14-产品结果" tabindex="-1">5. C01–C14 产品结果 <a class="header-anchor" href="#_5-c01–c14-产品结果" aria-label="Permalink to &quot;5. C01–C14 产品结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.5 准则</th><th style="text-align:right;">裁决</th><th>执行观察</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证</td><td style="text-align:right;"><strong>PASS</strong></td><td>九类强制错误 Schema 均产生 <code>SCHEMA_INVALID</code>，且没有形成权威节点。</td></tr><tr><td>C02</td><td>主载体与不可变性</td><td style="text-align:right;"><strong>PASS</strong></td><td>内容寻址修订与可归责 <code>CORRECTION</code> 证据保持完整；<code>parent</code> 通过 FCoP Markdown 投影和 Reader 重建。</td></tr><tr><td>C03</td><td>重复身份</td><td style="text-align:right;"><strong>PASS</strong></td><td>同 ID 异内容候选均被保留，无候选获胜，并产生确定性的关键冲突隔离。</td></tr><tr><td>C04</td><td>流连续性与异步推进</td><td style="text-align:right;"><strong>PASS</strong></td><td>重号、缺口被报告；无关流继续重建；没有虚构缺失对象；到达顺序不改变输出。</td></tr><tr><td>C05</td><td>角色权威</td><td style="text-align:right;"><strong>PASS</strong></td><td>权限拒绝与权限不确定分支均产生要求的问题，且不改变重建状态。</td></tr><tr><td>C06</td><td>生命周期合法性</td><td style="text-align:right;"><strong>PASS</strong></td><td>缺少独立验收时 <code>work_state</code> 保持 <code>review</code>，并同时产生 <code>LIFECYCLE_UNDETERMINED</code> 与 <code>ACCEPTANCE_UNDETERMINED</code>；非法及冲突状态分支也匹配。</td></tr><tr><td>C07</td><td>职责分离与人工控制</td><td style="text-align:right;"><strong>PASS</strong></td><td>同一身份使用不同角色标签被拒绝；高风险工作在 ADMIN 批准证据前保持 <code>pending_human</code>。</td></tr><tr><td>C08</td><td>完整性篡改</td><td style="text-align:right;"><strong>PASS</strong></td><td>被覆盖内容修改产生 <code>INTEGRITY_MISMATCH</code>；对象被排除出权威节点，同时失败来源仍保留在 Manifest。</td></tr><tr><td>C09</td><td>缺失引用</td><td style="text-align:right;"><strong>PASS</strong></td><td><code>MISSING_REFERENCE</code> 与 <code>CLAIM_EVIDENCE_MISSING</code> 持续可见；依赖与完成主张均未被视为满足。</td></tr><tr><td>C10</td><td>禁止引用环</td><td style="text-align:right;"><strong>PASS</strong></td><td>只隔离禁止环成员，无关有效节点仍保持权威。</td></tr><tr><td>C11</td><td>确定性重建</td><td style="text-align:right;"><strong>PASS</strong></td><td>固定四来源的 24 种排列产生字节等价的规范结果，SHA-256 为 <code>84e22cf795301ef0eaeaaa026154bfbef3d8cb94a49d3445484443fceaf0c85e</code>。</td></tr><tr><td>C12</td><td>冲突保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>矛盾复核保持 <code>disputed</code>；未授权 DEV 裁决作为证据保留但不能清除冲突；具有 <code>resolve_review_conflict</code> 权限的已分配 PM 可以解决。</td></tr><tr><td>C13</td><td>恢复</td><td style="text-align:right;"><strong>PASS</strong></td><td>全新 Reader 对生命周期、责任、未解决依赖、失败/恢复、父子状态和 <code>CHILD_WORK_OPEN</code> 的重建一致。</td></tr><tr><td>C14</td><td>终态历史保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>只有已验收、已授权的链进入 archive；任务、报告、复核、验收与状态转换历史均可重建。</td></tr></tbody></table><h1 id="_6-v1-4-0-→-v1-4-1-修复分析" tabindex="-1">6. V1.4.0 → V1.4.1 修复分析 <a class="header-anchor" href="#_6-v1-4-0-→-v1-4-1-修复分析" aria-label="Permalink to &quot;6. V1.4.0 → V1.4.1 修复分析&quot;">​</a></h1><p>修复对照严格限定范围。V1.4.0 已经通过 C02 与 C07；当时失败的是 C06 与 C12。</p><h2 id="_6-1-c06——生命周期不等于验收" tabindex="-1">6.1 C06——生命周期不等于验收 <a class="header-anchor" href="#_6-1-c06——生命周期不等于验收" aria-label="Permalink to &quot;6.1 C06——生命周期不等于验收&quot;">​</a></h2><p>V1.4.0 在生命周期证据看似充分、但缺少独立验收时仍允许 <code>review → done</code>，从而把流程推进与业务验收混为一体。V1.4.1 分别计算两类判断：没有独立验收，工作保持 <code>review</code>，同时输出生命周期与验收不确定。产品不再从不完整权威链中制造“完成”。</p><h2 id="_6-2-c12——只有授权解决者可以清除冲突" tabindex="-1">6.2 C12——只有授权解决者可以清除冲突 <a class="header-anchor" href="#_6-2-c12——只有授权解决者可以清除冲突" aria-label="Permalink to &quot;6.2 C12——只有授权解决者可以清除冲突&quot;">​</a></h2><p>V1.4.0 能保留矛盾复核，但允许后续未授权裁决清除争议。V1.4.1 保留未授权 DEV 裁决作为证据，产生权限问题，并让 <code>UNRESOLVED_CONFLICT</code> 继续有效。只有来自已分配、具有 <code>resolve_review_conflict</code> 权限的角色的裁决对象——本次以 PM 演示——才能解决冲突。</p><h2 id="_6-3-回归边界" tabindex="-1">6.3 回归边界 <a class="header-anchor" href="#_6-3-回归边界" aria-label="Permalink to &quot;6.3 回归边界&quot;">​</a></h2><p>C03 继续负责同 ID 异内容的候选冲突；C10 继续负责禁止引用环。两者都没有被并入 C12，且回归继续通过。若补丁通过弱化或重定义相邻准则来取得成功，就不能构成 S0.5 demonstrated 证据。</p><h1 id="_7-wp-13-多-agent-证据门禁案例" tabindex="-1">7. WP-13 多 Agent 证据门禁案例 <a class="header-anchor" href="#_7-wp-13-多-agent-证据门禁案例" aria-label="Permalink to &quot;7. WP-13 多 Agent 证据门禁案例&quot;">​</a></h1><p>WP-13 回答的问题不同于 C01–C14 Bundle：角色分离的工作流能否阻止未经核验的完成声明成为权威交付事实？</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>带完成含义的声明</span></span>
<span class="line"><span>        ↓ 持久证据不完整</span></span>
<span class="line"><span>PM 事实核验 → 暂停 / 不发布 / 不派 QA</span></span>
<span class="line"><span>        ↓ 同任务恢复</span></span>
<span class="line"><span>DEV Commit + Report</span></span>
<span class="line"><span>        ↓ 独立角色</span></span>
<span class="line"><span>QA 复跑与报告</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>授权 Gate C 裁决</span></span></code></pre></div><p>最初 DEV 子执行使用了带完成含义的语言，但退出状态、测试、Commit 与正式报告并未全部建立。PM 检查持久事实，暂停发布且未派 QA。恢复后，DEV 补齐证据，角色分离的 QA 重新执行测试与检查。后续 Gate C 记录完成业务验收；Active、Push/发布和 Archive 仍是分开的裁决。</p><p>该案例演示证据门禁、职责分离、同任务恢复与分阶段权威。它<strong>不证明</strong>模型不再产生幻觉，不保证所有错误声明都会被发现，也不表示原始 V3 快照已经包含终态批准。其快照边界记录 <code>runtime_bound: false</code>，TASK-019/020 仍为 <code>review / pending</code>；后续验收不得倒写为早期快照事实。</p>`,19)])])}const C=e(r,[["render",s]]);export{p as __pageData,C as default};
